import { useLanguage } from '../store/language.js';

/**
 * Translated app chrome only: navigation, page copy, form labels, and the
 * persistent play-page HUD. Career content generated by the engine
 * (scenario titles/prompts/option blurbs, perks, team/school/country names,
 * awards) is authored once in English and is not translated here - it is
 * data, not interface text, and lives in `packages/engine`.
 */
export interface Dictionary {
  nav: {
    play: string;
    leaderboard: string;
    footer: string;
    languageLabel: string;
  };
  home: {
    headline: string;
    headlineAccent: string;
    subhead: string;
    startNew: string;
    resume: string;
    keepPlaying: string;
    startYourCareer: string;
    noSignup: string;
    arc: readonly [string, string, string];
    sampleCallLabel: string;
    sampleCall: {
      kicker: string;
      title: string;
      prompt: string;
      options: ReadonlyArray<{ label: string; blurb: string }>;
    };
    tagline: readonly [string, string];
  };
  createPlayer: {
    title: string;
    name: string;
    namePlaceholder: string;
    jersey: string;
    bornIn: string;
    shootingHand: string;
    lefty: string;
    righty: string;
    position: string;
    archetypeLabel: (position: string) => string;
    submit: string;
  };
  play: {
    lastCall: string;
    overall: string;
    fame: string;
    status: string;
    chemistry: string;
    bank: string;
    salary: string;
    value: string;
    tradeRisk: string;
    contentionWindow: string;
    clubIdolatry: string;
    nationalTeamLabel: (country: string) => string;
    ratings: {
      finishing: string;
      midRange: string;
      threePoint: string;
      playmaking: string;
      defense: string;
      rebounding: string;
      basketballIQ: string;
      athleticism: string;
      durability: string;
    };
    gold: string;
    perksShop: {
      ariaLabel: string;
      tooltip: (active: number, bank: string) => string;
      title: string;
      subtitle: string;
      inTheBank: string;
      close: string;
      empty: string;
      owned: string;
      need: (cost: string) => string;
      perYear: string;
      once: string;
    };
  };
  errorBoundary: {
    title: string;
    body: string;
    button: string;
  };
}

