const dictionaries = { en, es };

/** Reactive dictionary lookup for function components. */
export function useT(): Dictionary {
  const lang = useLanguage((s) => s.lang);
  return dictionaries[lang];
}

/** Non-reactive lookup for class components (e.g. ErrorBoundary) that can't use hooks. */
export function getT(): Dictionary {
  return dictionaries[useLanguage.getState().lang];
}
